package vn.svframe.svframelib.api.event.mitigation;import vn.svframe.svframelib.api.player.MMOPlayerData;import vn.svframe.svframelib.damage.AttackMetadata;public class PlayerBlockEvent{private final MMOPlayerData player;private final AttackMetadata attack;private boolean cancelled;public PlayerBlockEvent(MMOPlayerData player,AttackMetadata attack){this.player=player;this.attack=attack;}public MMOPlayerData getPlayerData(){return player;}public AttackMetadata getAttack(){return attack;}public boolean isCancelled(){return cancelled;}public void setCancelled(boolean c){cancelled=c;}}